from __future__ import annotations

from typing import Any

import pytest
from ds.ai import smashtube
from ds.data.raw.smashtube import MatchVideos, VideoQuery
from pydantic_ai import ModelRetry


@pytest.fixture
def calls(monkeypatch: pytest.MonkeyPatch) -> list[dict[str, Any]]:
    seen: list[dict[str, Any]] = []

    def fake_search(**kwargs: Any) -> MatchVideos:
        seen.append(kwargs)
        return MatchVideos(query=VideoQuery(), total="0", page=1, pages=1, videos=[], source_url="u")

    monkeypatch.setattr(smashtube, "search_videos", fake_search)
    return seen


def test_characters_are_normalized_to_char_ids(calls: list[dict[str, Any]]) -> None:
    smashtube.find_match_videos(player_1="Sparg0", char_1="Little Mac", char_2="cloud", region="na")
    assert calls[0]["char_1"] == "little_mac"
    assert calls[0]["char_2"] == "cloud"
    assert calls[0]["region"] == "NA"


def test_empty_characters_are_not_resolved(calls: list[dict[str, Any]]) -> None:
    smashtube.find_match_videos(player_1="Sparg0")
    assert (calls[0]["char_1"], calls[0]["char_2"]) == ("", "")


@pytest.mark.parametrize(
    "kwargs",
    [{"char_1": "not a character"}, {"player_1": "x", "region": "Mars"}, {"search_term": "x" * 21}],
)
def test_bad_input_asks_model_to_retry(calls: list[dict[str, Any]], kwargs: dict[str, Any]) -> None:
    with pytest.raises(ModelRetry):
        smashtube.find_match_videos(**kwargs)
    assert calls == []


def test_no_filter_asks_model_to_retry() -> None:
    with pytest.raises(ModelRetry, match="at least one"):
        smashtube.find_match_videos()


@pytest.mark.parametrize(
    ("kwargs", "players", "chars"),
    [
        # the character is the default reading of an ambiguous name
        ({"player_1": "Joker", "char_1": "little_mac"}, ("", ""), ("little_mac", "joker")),
        ({"player_1": "Joker"}, ("", ""), ("joker", "")),
        ({"player_1": "Sparg0", "player_2": "little mac"}, ("Sparg0", ""), ("", "little_mac")),
        ({"player_1": "cloud", "char_1": "cloud"}, ("", ""), ("cloud", "")),
        # both character slots taken: it must be a person
        ({"player_1": "Joker", "char_1": "fox", "char_2": "cloud"}, ("Joker", ""), ("fox", "cloud")),
        # the user said it is a tag
        ({"player_1": "Joker", "players_are_tags": True}, ("Joker", ""), ("", "")),
        # not a character name: untouched
        ({"player_1": "Jokerman"}, ("Jokerman", ""), ("", "")),
    ],
)
def test_character_names_in_player_fields_become_characters(
    calls: list[dict[str, Any]], kwargs: dict[str, Any], players: tuple[str, str], chars: tuple[str, str]
) -> None:
    smashtube.find_match_videos(**kwargs)
    assert (calls[0]["player_1"], calls[0]["player_2"]) == players
    assert (calls[0]["char_1"], calls[0]["char_2"]) == chars
